import{_ as o,o as r,c as a,ag as e}from"./chunks/framework.Aev9KvMf.js";const u=JSON.parse('{"title":"白名单例外：市场化投诉平台的显式标注收录","description":"","frontmatter":{},"headers":[],"relativePath":"project/adr/0018-market-complaint-platforms.md","filePath":"project/adr/0018-market-complaint-platforms.md"}'),n={name:"project/adr/0018-market-complaint-platforms.md"};function s(l,t,i,p,_,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="白名单例外-市场化投诉平台的显式标注收录" tabindex="-1">白名单例外：市场化投诉平台的显式标注收录 <a class="header-anchor" href="#白名单例外-市场化投诉平台的显式标注收录" aria-label="Permalink to &quot;白名单例外：市场化投诉平台的显式标注收录&quot;">​</a></h1><p>用户要求收录黑猫投诉等消费者投诉平台。黑猫投诉（新浪旗下）为<strong>商业化平台</strong>，与 ADR 0002&quot;白名单外一律不收&quot;及&quot;不背书&quot;红线存在冲突。经权衡，作为<strong>显式例外</strong>处理，而非打破白名单：</p><ol><li><strong>收录形态</strong>：不单独成篇，置于《投诉举报渠道全景》页内&quot;市场化平台&quot;小节，与官方渠道（12315/12345/12321/12377/互联网+督查）<strong>物理分区</strong>。</li><li><strong>标注义务</strong>：页首 danger 框 + 条目内重复声明&quot;非官方、无行政强制力、不背书其处理结果&quot;；官方渠道永远排在前面。</li><li><strong>不背书的边界</strong>：黑猫投诉等平台的处理结果不作为本站任何词条的引用来源；它们只出现在&quot;维权路径&quot;语境，不进入内容溯源链。</li><li><strong>扩展约束</strong>：此类例外平台仅限&quot;投诉/曝光&quot;这一种社会监督功能；测评、种草、榜单类商业内容永不收录（守住 ADR 0002 反带货红线的本意）。</li></ol><p>同页一并收录官方举报矩阵（12345 综合热线、12321 骚扰信息、12377 网络违法信息、互联网+督查）， filling 此前只有 12315 单点的空白。</p>',4)])])}const d=o(n,[["render",s]]);export{u as __pageData,d as default};
